// In MainWindow, before the main HorizontalLayout or after it
fs := FocusScope {
    key-pressed(event) => {
        if (event.text == Key.Left) {
            if (root.active-tab > 0) { root.active-tab -= 1; }
            accept
        } else if (event.text == Key.Right) {
            if (root.active-tab < 3) { root.active-tab += 1; }
            accept
        } else {
            reject
        }
    }
}
